	}
	m := r.Method
	switch {
	case len(seg) == 1 && seg[0] == "me" && m == "GET":
		a.me(w, u)
	case len(seg) == 1 && seg[0] == "teams" && m == "GET":
		a.myTeams(w, u)
	case len(seg) == 1 && seg[0] == "teams" && m == "POST":
