	}
	if !strings.HasPrefix(path, "/") {
		notFound(w)
		return
	}
	parts := strings.Split(path[1:], "/")
	seg := make([]string, len(parts))
	for i, p := range parts {
		d, err := url.PathUnescape(p)
		if err != nil || p == "" {
			notFound(w)
			return
		}
		seg[i] = d
	}
	m := r.Method
	switch {
	case len(seg) == 1 && seg[0] == "me" && m == "GET":
		a.me(w, u)
	case len(seg) == 1 && seg[0] == "teams" && m == "GET":
