		a.putMember(w, r, u, seg[1], seg[3])
	case len(seg) == 4 && seg[0] == "teams" && seg[2] == "members" && m == "DELETE":
		a.delMember(w, r, u, seg[1], seg[3])
	case len(seg) == 3 && seg[0] == "teams" && seg[2] == "notes" && m == "GET":
		a.listNotes(w, r, u, seg[1])
